package cli

import (
	"crypto/x509"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// vectorKDF matches the kdf section in vectors.json.
type vectorKDF struct {
	Algorithm string    `json:"algorithm"`
	Salt      string    `json:"salt"`
	Params    kdfParams `json:"params"`
}

type vectorVariable struct {
	Key            string `json:"key"`
	Value          string `json:"value"`
	EncryptedKey   string `json:"encrypted_key"`
	EncryptedValue string `json:"encrypted_value"`
}

// cryptoVectors matches the file generated by ui/scripts/cli-vectors.mjs.
type cryptoVectors struct {
	Password            string           `json:"password"`
	KDF                 vectorKDF        `json:"kdf"`
	AuthKey             string           `json:"auth_key"`
	WrapKey             string           `json:"wrap_key"`
	PublicKey           string           `json:"public_key"`
	PrivateKeyPKCS8     string           `json:"private_key_pkcs8"`
	EncryptedPrivateKey string           `json:"encrypted_private_key"`
	ProjectKey          string           `json:"project_key"`
	WrappedProjectKey   string           `json:"wrapped_project_key"`
	Variables           []vectorVariable `json:"variables"`
}

func loadVectors(t *testing.T) cryptoVectors {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "vectors.json"))
	if err != nil {
		t.Fatalf("membaca testdata/vectors.json gagal: %v (generate ulang: cd ui && node scripts/cli-vectors.mjs)", err)
	}
	var vectors cryptoVectors
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatalf("vectors.json tidak valid: %v", err)
	}
	return vectors
}

// TestVectorsInterop verifies that the Go implementation derives and decrypts
// the same values as the browser implementation (WebCrypto + hash-wasm).
func TestVectorsInterop(t *testing.T) {
	vectors := loadVectors(t)

	if vectors.KDF.Algorithm != "argon2id" {
		t.Fatalf("algorithm tak terduga: %q", vectors.KDF.Algorithm)
	}

	masterKey, err := deriveMasterKey(vectors.Password, vectors.KDF.Salt, vectors.KDF.Params)
	if err != nil {
		t.Fatalf("deriveMasterKey: %v", err)
	}
	defer wipeBytes(masterKey)

	authKey, err := deriveAuthKey(masterKey)
	if err != nil {
		t.Fatalf("deriveAuthKey: %v", err)
	}
	if authKey != vectors.AuthKey {
		t.Fatalf("authKey tidak cocok dengan vektor browser:\n got %s\nwant %s", authKey, vectors.AuthKey)
	}

	wrapKey, err := deriveWrapKey(masterKey)
	if err != nil {
		t.Fatalf("deriveWrapKey: %v", err)
	}
	if got := b64Encode(wrapKey); got != vectors.WrapKey {
		t.Fatalf("wrapKey tidak cocok dengan vektor browser")
	}

	privateKey, err := decryptPrivateKey(wrapKey, vectors.EncryptedPrivateKey)
	if err != nil {
		t.Fatalf("decryptPrivateKey: %v", err)
	}

	// The private key must match the public key in the test vector.
	spki, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
	if err != nil {
		t.Fatalf("marshal public key: %v", err)
	}
	if got := b64Encode(spki); got != vectors.PublicKey {
		t.Fatalf("public key hasil dekripsi tidak cocok dengan vektor")
	}

	// The decrypted PKCS#8 key must match the original private key in the vector.
	pkcs8, err := x509.MarshalPKCS8PrivateKey(privateKey)
	if err != nil {
		t.Fatalf("marshal pkcs8: %v", err)
	}
	if got := b64Encode(pkcs8); got != vectors.PrivateKeyPKCS8 {
		t.Fatalf("PKCS#8 hasil dekripsi tidak identik dengan vektor")
	}

	projectKey, err := unwrapProjectKey(privateKey, vectors.WrappedProjectKey)
	if err != nil {
		t.Fatalf("unwrapProjectKey: %v", err)
	}
	if got := b64Encode(projectKey); got != vectors.ProjectKey {
		t.Fatalf("project key tidak cocok dengan vektor")
	}

	for _, variable := range vectors.Variables {
		name, err := decryptVariable(projectKey, variable.EncryptedKey)
		if err != nil {
			t.Fatalf("decrypt nama %q: %v", variable.Key, err)
		}
		if name != variable.Key {
			t.Fatalf("nama variable: got %q want %q", name, variable.Key)
		}
		value, err := decryptVariable(projectKey, variable.EncryptedValue)
		if err != nil {
			t.Fatalf("decrypt nilai %q: %v", variable.Key, err)
		}
		if value != variable.Value {
			t.Fatalf("nilai variable %q: got %q want %q", variable.Key, value, variable.Value)
		}
	}
}

// TestDecryptRejectsTamperedBlob verifies that AES-GCM authentication is enforced.
func TestDecryptRejectsTamperedBlob(t *testing.T) {
	vectors := loadVectors(t)
	projectKey, err := b64Decode(vectors.ProjectKey)
	if err != nil {
		t.Fatalf("decode project key: %v", err)
	}
	blob := []byte(vectors.Variables[0].EncryptedValue)
	// Change one base64 character without changing the encoded length.
	if blob[10] == 'A' {
		blob[10] = 'B'
	} else {
		blob[10] = 'A'
	}
	if _, err := decryptVariable(projectKey, string(blob)); err == nil {
		t.Fatal("blob yang dimodifikasi seharusnya ditolak (auth tag)")
	}
}

func TestParseKDFParams(t *testing.T) {
	params, err := parseKDFParams("")
	if err != nil {
		t.Fatalf("parse kosong: %v", err)
	}
	if params != defaultKDFParams() {
		t.Fatalf("default params tidak sesuai: %+v", params)
	}

	partial, err := parseKDFParams(`{"t":4}`)
	if err != nil {
		t.Fatalf("parse partial: %v", err)
	}
	if partial.Iterations != 4 || partial.Memory != 65536 {
		t.Fatalf("merge dengan default gagal: %+v", partial)
	}

	if _, err := parseKDFParams("bukan-json"); err == nil {
		t.Fatal("JSON rusak seharusnya error")
	}
	if _, err := parseKDFParams(`{"m":0,"t":0,"p":0,"hash_length":0}`); err == nil {
		t.Fatal("params tidak lengkap seharusnya error")
	}
}
